<script setup>
import { computed, ref } from 'vue'
import { Link, useForm } from '@inertiajs/vue3'
import DashboardLayout from '@/Layouts/DashboardLayout.vue'
import Card from '@/Components/Card.vue'
import Button from '@/Components/Button.vue'
import Modal from '@/Components/Modal.vue'
import FormInput from '@/Components/FormInput.vue'
import FormSelect from '@/Components/FormSelect.vue'
import FormTextarea from '@/Components/FormTextarea.vue'
const props = defineProps({ plan: Object, bankAccounts: Array })
const paymentOpen = ref(false), cancelOpen = ref(false)
const next = computed(() => props.plan.installments.find(item => item.status !== 'paid'))
const payment = useForm({ payment_plan_installment_id: '', amount: '', payment_date: new Date().toISOString().slice(0, 10), payment_method: 'bank_transfer', bank_account: '', reference: '' })
const cancellation = useForm({ reason: '' })
const money = amount => new Intl.NumberFormat('es-AR', { style: 'currency', currency: 'ARS' }).format(amount || 0)
const openPayment = () => { payment.payment_plan_installment_id = String(next.value?.id || ''); payment.amount = Math.max(0, Number(next.value?.amount || 0) - Number(next.value?.paid_amount || 0)).toFixed(2); paymentOpen.value = true }
const pay = () => payment.post(route('payment-plans.pay', props.plan.id), { onSuccess: () => paymentOpen.value = false })
const cancel = () => cancellation.post(route('payment-plans.cancel', props.plan.id), { onSuccess: () => cancelOpen.value = false })
</script>
<template><DashboardLayout :title="`Plan #${plan.id}`"><div class="mb-4"><Link :href="route('payment-plans.index')" class="text-emerald-700 hover:underline">← Volver a planes</Link></div><Card :title="`${plan.uf_number} — ${plan.owner}`"><template #header-actions><div v-if="plan.status === 'active'" class="flex gap-2"><Button @click="openPayment">Registrar Pago</Button><Button variant="danger" @click="cancelOpen = true">Cancelar Plan</Button></div></template><div class="grid gap-4 sm:grid-cols-4 text-sm"><div><span class="text-slate-500">Total original</span><p class="font-semibold">{{ money(plan.original_amount) }}</p></div><div><span class="text-slate-500">Abonado</span><p class="font-semibold">{{ money(plan.paid_amount) }}</p></div><div><span class="text-slate-500">Saldo</span><p class="font-semibold">{{ money(plan.outstanding_amount) }}</p></div><div><span class="text-slate-500">Estado</span><p class="font-semibold capitalize">{{ plan.status }}</p></div></div><p v-if="plan.notes" class="mt-4 text-sm text-slate-600">{{ plan.notes }}</p><p v-if="plan.cancellation_reason" class="mt-2 text-sm text-red-700">Motivo de cancelación: {{ plan.cancellation_reason }}</p></Card><Card class="mt-5" title="Cuotas"><div class="overflow-x-auto"><table class="w-full text-sm"><thead class="bg-slate-50"><tr><th class="p-3 text-left">Cuota</th><th class="p-3 text-left">Vencimiento</th><th class="p-3 text-right">Importe</th><th class="p-3 text-right">Pagado</th><th class="p-3 text-left">Estado</th></tr></thead><tbody class="divide-y"><tr v-for="item in plan.installments" :key="item.id"><td class="p-3">{{ item.number }}</td><td class="p-3">{{ item.due_date }}</td><td class="p-3 text-right">{{ money(item.amount) }}</td><td class="p-3 text-right">{{ money(item.paid_amount) }}</td><td class="p-3 capitalize">{{ item.status }}</td></tr></tbody></table></div></Card><Card class="mt-5" title="Deuda incluida"><div class="text-sm space-y-2"><div v-for="item in plan.items" :key="item.period" class="flex justify-between border-b pb-2"><span>{{ item.period }}</span><span>{{ money(item.financed_amount) }} financiado / {{ money(item.settled_amount) }} cancelado</span></div></div></Card><Card class="mt-5" title="Historial de pagos"><div v-if="plan.payments.length" class="space-y-2 text-sm"><div v-for="(item, index) in plan.payments" :key="index" class="flex justify-between border-b pb-2"><span>{{ item.date }} · {{ item.method }}</span><span>{{ money(item.amount) }}</span></div></div><p v-else class="text-sm text-slate-500">Sin pagos registrados.</p></Card><Modal :show="paymentOpen" title="Registrar pago de cuota" @close="paymentOpen = false"><form class="space-y-4" @submit.prevent="pay"><FormSelect v-model="payment.payment_plan_installment_id" label="Cuota" :options="plan.installments.filter(i => i.status !== 'paid').map(i => ({ value: String(i.id), label: `Cuota ${i.number} — saldo ${money(i.amount - i.paid_amount)}` }))" required/><FormInput v-model="payment.amount" type="number" min="0.01" step="0.01" label="Monto" required/><FormInput v-model="payment.payment_date" type="date" label="Fecha" required/><FormSelect v-model="payment.payment_method" label="Método" :options="[{value:'cash',label:'Efectivo'},{value:'bank_transfer',label:'Transferencia bancaria'},{value:'check',label:'Cheque'},{value:'other',label:'Otro'}]"/><FormSelect v-model="payment.bank_account" label="Cuenta bancaria" :options="bankAccounts" :disabled="payment.payment_method === 'cash'"/><FormTextarea v-model="payment.reference" label="Referencia" :rows="2"/></form><template #footer><div class="flex justify-end gap-2"><Button variant="secondary" @click="paymentOpen = false">Cancelar</Button><Button :loading="payment.processing" @click="pay">Registrar</Button></div></template></Modal><Modal :show="cancelOpen" title="Cancelar plan" @close="cancelOpen = false"><FormTextarea v-model="cancellation.reason" label="Motivo (opcional)" :rows="3"/><p class="mt-4 text-sm text-red-700">Solo volverá a deuda corriente el saldo impago: {{ money(plan.outstanding_amount) }}.</p><template #footer><div class="flex justify-end gap-2"><Button variant="secondary" @click="cancelOpen = false">Volver</Button><Button variant="danger" :loading="cancellation.processing" @click="cancel">Confirmar cancelación</Button></div></template></Modal></DashboardLayout></template>
